do $payload_check$
begin
  if (select count(*) from _paid_queue_193) <> 193
     or (select count(distinct content_key) from _paid_queue_193) <> 193
     or (select count(distinct (word,zh,level)) from _paid_queue_193) <> 193
     or (select count(distinct word) from _paid_queue_193) <> 192
     or (select count(*) from _paid_queue_193 where word='คัน' and zh in('輛','癢')) <> 2
     or (select count(*) from _paid_queue_193 where level='初') <> 186
     or (select count(*) from _paid_queue_193 where level='中') <> 7
     or exists(select 1 from _paid_queue_193 where access_tier <> 'paid' or catalog_version <> 'paid-queue-193-v1' or audio_status <> 'รอตรวจรวม')
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from _paid_queue_193) <> '906441641a315015fbf64d1ebf78d863' then
    raise exception 'Paid 193 payload invariant failed';
  end if;
  if exists(select 1 from public.game_words g join _paid_queue_193 p using(content_key)) then
    raise exception 'Paid 193 content_key collides with the existing central catalog';
  end if;
  if exists(select 1 from public.game_words g join _paid_queue_193 p using(word)) then
    raise exception 'Paid 193 written form collides with the existing central catalog; semantic review required';
  end if;
end
$payload_check$;

insert into public.game_words(
  content_key,word,en,zh,level,category,syls,reading_th,read_syls,rank,spelling_th,audio_status,type,subcategory,
  access_tier,catalog_version,record_hash,canonical_record,status,updated_at
)
select content_key,word,en,zh,level,category,syls,reading_th,null,rank,spelling_th,audio_status,type,subcategory,
       access_tier,catalog_version,record_hash,canonical_record,'queued',now()
from _paid_queue_193;

alter table public.game_words enable row level security;
revoke all on table public.game_words from public,anon,authenticated;
grant select on table public.game_words to service_role;

do $postcheck$
begin
  if (select count(*) from public.game_words where status='active') <> 200
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from public.game_words where status='active') <> 'c4f7b191b4e7c812ab4e348dccdf7ced'
     or (select count(*) from public.game_words where status='queued' and access_tier='paid') <> 382
     or (select count(*) from public.game_words where status='queued' and access_tier='paid' and level='初') <> 369
     or (select count(*) from public.game_words where status='queued' and access_tier='paid' and level='中') <> 13
     or (select count(*) from public.game_words where catalog_version='paid-queue-189-v1') <> 189
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from public.game_words where catalog_version='paid-queue-189-v1') <> '8995b40864da1d4f6a04d483c13f3114'
     or (select count(*) from public.game_words where catalog_version='paid-queue-193-v1') <> 193
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from public.game_words where catalog_version='paid-queue-193-v1') <> '906441641a315015fbf64d1ebf78d863'
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from public.game_words where status='queued' and access_tier='paid') <> '68fa6e62e25e55f48c38bad7db812391'
     or (select count(*) from public.phase1_product_entitlements where entitlement='owner_all_access') <> 1 then
    raise exception 'Central catalog 582 postcheck failed';
  end if;
  if has_table_privilege('anon','public.game_words','select') or has_table_privilege('authenticated','public.game_words','select') then
    raise exception 'browser role can read protected vocabulary catalog';
  end if;
end
$postcheck$;

notify pgrst,'reload schema';
commit;
